511	void LiaStarExtension::lazyCheckStar(Node literal, Node lambda)
512	{
513	  // Lazy reduction: drive one refinement round for `literal`. Stop refining
514	  // once the literal has been fully reduced (its term marked processed).
515	  if (std::find(
516	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
517	      != d_processedStarTerms.end())
518	  {
519	    return;
520	  }
521	
522	  // The persistent incremental subsolver for this lambda. On first use it is
523	  // seeded with the (nonnegative) predicate.
524	  Subsolver& sub = getSubsolver(lambda);
525	
526	  // Refine the subsolver with the cone-disjuncts discovered since the previous
527	  // round. The refined formula -- the negated union of every disjunct found so
528	  // far -- subsumes the previous round's, so instead of accumulating one
529	  // assertion per disjunct we pop the previous refined formula and assert the
530	  // new one in a fresh frame: the subsolver always holds just the base
531	  // predicate (at the base user level) plus a single refined formula. The
532	  // disjuncts are stored in bound-variable space, so map them to skolem space
533	  // first.
534	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& pairs =
535	      d_lazyCones[lambda];
536	  if (sub.negated < pairs.size())
537	  {
538	    for (size_t i = sub.negated; i < pairs.size(); i++)
539	    {
540	      Node disjunct = pairs[i].first;
541	      if (!sub.from.empty())
542	      {
543	        disjunct = disjunct.substitute(
544	            sub.from.begin(), sub.from.end(), sub.to.begin(), sub.to.end());
545	      }
546	      sub.covered = sub.covered.isNull()
547	                        ? disjunct
548	                        : d_nm->mkNode(Kind::OR, sub.covered, disjunct);
549	    }
550	    sub.negated = pairs.size();
551	    if (sub.pushed)
552	    {
553	      sub.engine->pop();
554	    }
555	    sub.engine->push();
556	    sub.engine->assertFormula(sub.covered.notNode());
557	    sub.pushed = true;
558	  }
559	
560	  lazyHilbert(literal, sub);
561	}
