627	void LiaStarExtension::addCone(
628	    Node n, const std::pair<std::vector<std::string>, Node>& pair)
629	{
630	  // Lazy path: build the cone for a single disjunct `pair` and append it to the
631	  // cones accumulated so far for this lambda (n[0]). An empty (infeasible) cone
632	  // is dropped.
633	  size_t dimension = n.getNumChildren() - 1;
634	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& cones =
635	      d_lazyCones[n[0]];
636	
637	  Trace("liastar-ext") << "---------------------------" << std::endl;
638	  Trace("liastar-ext") << "Cone for node " << std::endl
639	                       << pair.second << std::endl;
640	
641	  Cone<Integer> cone = LiaStarUtils::buildCone(dimension, pair.first);
642	  if (LiaStarUtils::isEmptyCone(cone))
643	  {
644	    Trace("liastar-ext") << "empty cone" << std::endl;
645	    return;
646	  }
647	  cones.push_back({pair.second, cone});
648	}
