800	void LiaStarExtension::lazyHilbert(Node literal, Subsolver& sub)
801	{
802	  // One lazy refinement round for `literal`. Ask the subsolver for a model in a
803	  // region of p not yet covered by a cone, read off the convex cell containing
804	  // it, turn it into a cone, and emit a (tentative or final) reduction lemma.
805	  Node variables = literal[0][0];
806	  Trace("liastar-lazy") << "lazyHilbert::variables:" << variables << std::endl;
807	
808	  traceSmtPreamble(variables);
809	
810	  // Check the subsolver and read off the disjunct (the cell of the predicate)
811	  // containing the model. The subsolver already has the predicate and the
812	  // negations of all previously discovered cone-disjuncts asserted, so the
813	  // model lies in a region of the predicate not yet covered by any cone.
814	  Node disjunct = LiaStarUtils::getDisjunct(
815	      sub.base, sub.from, sub.to, &d_env, sub.engine.get());
816	  // `getDisjunct` returns false when no region of `formula` is left uncovered,
817	  // i.e. every disjunct of the predicate already has a cone. At that point the
818	  // cone encoding is exact and we can assert the full equivalence.
819	  bool complete = disjunct == d_false;
820	  // The disjunct is a conjunction of arithmetic facts in the subsolver's
821	  // normal form, which can represent strict inequalities as negations (e.g.
822	  // (not (>= a b))). Normalize away the negations before building the matrix.
823	  disjunct = LiaStarUtils::removeItesAndNots(disjunct, &d_env);
824	
825	  Trace("liastar-ext") << "disjunct: " << disjunct << std::endl;
826	
827	  std::pair<std::vector<std::string>, Node> pair =
828	      LiaStarUtils::getMatrix(variables, disjunct);
829	
830	  Trace("liastar-ext") << "disjunct: " << disjunct << std::endl;
831	
832	  // Add the cone for the current disjunct to `d_lazyCones` and get the starLia
833	  // constraints over the whole list of cones so far. `getStarConstraints` only
834	  // computes the per-cone constraints (and fresh skolems) for cones not yet
835	  // processed, reusing the constraints computed in previous calls. When
836	  // `complete`, `disjunct` is the (infeasible) false constraint, so `addCone`
837	  // adds no new cone and `getStarConstraints` just rebuilds the sum constraints
838	  // over the cones found so far.
839	  addCone(literal, pair);
840	  std::vector<Node> starConstraints = getStarConstraints(literal);
841	  Trace("liastar-ext") << "starConstraints: " << std::endl
842	                       << toString(starConstraints) << std::endl;
843	
844	  Node star = d_nm->mkNode(Kind::AND, starConstraints);
845	
846	  Trace("liastar-ext") << d_lazyCones[literal[0]].size()
847	                       << " cones for lambda:  " << literal[0] << std::endl;
848	
849	  star = rewrite(star);
850	  // Remember the last computed starLia under-approximation for `literal`; the
851	  // model-value check in checkFullEffort uses it to skip refinement when the
852	  // current model already satisfies it.
853	  d_lastStarLia[literal] = star;
854	
855	  // Deactivate the guard from the previous refinement round for this literal:
856	  // its under-approximation is a subset of the current `star`, so the tentative
857	  // equivalence it guarded is subsumed. Asserting `(not g_old)` makes that
858	  // guarded lemma vacuous, so the solver does not have to satisfy several
859	  // (mutually constraining) guarded equivalences at once. Sound because `g_old`
860	  // is fresh.
861	  auto guardIt = d_lastGuard.find(literal);
862	  if (guardIt != d_lastGuard.end())
863	  {
864	    Node deactivate = guardIt->second.notNode();
865	    if (d_proofGen != nullptr)
866	    {
867	      d_proofGen->registerGuardDeactivate(deactivate);
868	    }
869	    d_im.addPendingLemma(
870	        deactivate, InferenceId::ARITH_LIA_STAR_SPLIT, d_proofGen.get());
871	    d_lastGuard.erase(guardIt);
872	  }
873	
874	  Node lemma;
875	  if (complete)
876	  {
877	    // The encoding is complete, so `star` captures the star set exactly and the
878	    // full equivalence holds. This is what allows refuting a (positively
879	    // asserted) star-contains.
880	    lemma = literal.eqNode(star);
881	  }
882	  else
883	  {
884	    // While cones are still being discovered, `star` is an under-approximation
885	    // of the star set, so the equivalence `literal = star` is not yet sound. We
886	    // assert it only tentatively, implied by a fresh boolean guard `g`. The
887	    // split makes `g` a genuine decision literal and `preferPhase` biases it to
888	    // true, so the SAT solver tries the equivalence first. If assuming it leads
889	    // to a conflict (the literal actually holds via a not-yet-discovered cone),
890	    // the solver flips `g` to false, retracting the equivalence, and we refine.
891	    Node g = d_nm->mkDummySkolem("liastarGuard", d_nm->booleanType());
892	    g = d_astate.getValuation().ensureLiteral(g);
893	    d_im.preferPhase(g, true);
894	    Node split = g.orNode(g.notNode());
895	    if (d_proofGen != nullptr)
896	    {
897	      d_proofGen->registerSplit(split, g);
898	    }
899	    d_im.addPendingLemma(
900	        split, InferenceId::ARITH_LIA_STAR_SPLIT, d_proofGen.get());
901	    lemma = g.impNode(literal.eqNode(star));
902	    // Remember this guard so it can be deactivated once a later, larger
903	    // under-approximation subsumes it.
904	    d_lastGuard[literal] = g;
905	  }
906	  Trace("liastar-ext") << "star lemma: " << lemma << std::endl;
907	  if (d_proofGen != nullptr)
908	  {
909	    d_proofGen->registerContainsReduce(lemma, literal, star);
910	  }
911	  d_im.addPendingLemma(
912	      lemma, InferenceId::ARITH_LIA_STAR_EXISTS, d_proofGen.get());
913	  // Keep refining (do not mark the term processed) until every disjunct of the
914	  // predicate has been covered by a cone.
915	  if (complete)
916	  {
917	    d_processedStarTerms.push_back(literal);
918	  }
919	  d_im.doPendingLemmas();
920	}
