293	  Trace("liastar-ext") << "---------------------" << std::endl;
294	  for (auto it = d_arith.facts_begin(); it != d_arith.facts_end(); ++it)
295	  {
296	    Node lit = (*it).d_assertion;
297	    Trace("liastar-ext") << lit << std::endl;
298	    if (lit.getKind() == Kind::STAR_CONTAINS)
299	    {
300	      // positive polarity of star-contains
301	      assertions.push_back(lit);
302	    }
303	    if (lit.getKind() == Kind::NOT && lit[0].getKind() == Kind::STAR_CONTAINS)
304	    {
305	      // negative polarity of star-contains
306	      assertions.push_back(lit[0]);
307	    }
308	  }
309	  Trace("liastar-ext") << "---------------------" << std::endl;
310	}
