882	std::pair<std::vector<std::string>, Node> LiaStarUtils::getMatrix(
883	    Node variables, Node n)
884	{
885	  // Render a single cone (a conjunction of linear (in)equalities, or one
886	  // atom/boolean constant) into a list of Normaliz "symbolic" constraint
887	  // strings paired with the original node `n`. The boolean constants are
888	  // encoded as the trivially-true row "x[1] = x[1];" and the infeasible row
889	  // "1 = 0;".
890	  Assert(n.getType().isBoolean()) << "n: " << n << std::endl;
891	  Kind k = n.getKind();
892	  switch (k)
893	  {
894	    case Kind::CONST_BOOLEAN:
895	    {
896	      bool value = n.getConst<bool>();
897	      std::string constraint = value ? "x[1] = x[1];" : "1 = 0;";
898	      std::vector<std::string> constraints{constraint};
899	      return {constraints, n};
900	    }
901	    case Kind::LT:
902	    case Kind::GT:
903	    case Kind::LEQ:
904	    case Kind::GEQ:
905	    case Kind::EQUAL:
906	    {
907	      // a comparison "lhs <op> rhs;" with each side printed as a linear term
908	      linear::Polynomial l = linear::Polynomial::parsePolynomial(n[0]);
909	      linear::Polynomial r = linear::Polynomial::parsePolynomial(n[1]);
910	      std::string lTerm = getString(variables, l);
911	      std::string rTerm = getString(variables, r);
912	      std::string kString = k == Kind::LT    ? " < "
913	                            : k == Kind::GT  ? " > "
914	                            : k == Kind::LEQ ? " <= "
915	                            : k == Kind::GEQ ? " >= "
916	                                             : " = ";
917	      std::string constraint = lTerm + kString + rTerm + ";";
918	      std::vector<std::string> constraints{constraint};
919	      return {constraints, n};
920	    }
921	    case Kind::AND:
922	    {
923	      // one row per conjunct (each conjunct is a single-constraint atom)
924	      std::vector<std::string> constraints;
925	      for (size_t i = 0; i < n.getNumChildren(); i++)
926	      {
927	        std::pair<std::vector<std::string>, Node> m =
928	            getMatrix(variables, n[i]);
929	        constraints.push_back(m.first[0]);
930	      }
931	      return {constraints, n};
932	    }
933	
934	    default:
935	    {
936	      InternalError() << "Unexpected kind. Node " << n
937	                      << " has kind: " << n.getKind() << std::endl;
938	    };
939	  }
